  ('NightLark', false, true, 'Online only', 'Online', 'cutting', array['I05','I06','D01','M05','M06']::text[], array['chat','groups']::text[], 'Tapering off benzos with my GP. I sleep badly so I''m up late a lot. Synth music, co-op games, long chats at 2am.'),
