  ('SteadyBadger', true, false, 'North-east', 'Online', 'long', array['I01','I08','I09','M01','S05','D01']::text[], array['listen','accountability','walk']::text[], 'Four years clear of opioids. Peer mentor. I cook too much and I walk a lot. Happy to just listen, whatever stage you''re at.'),
